    "\u5b57\u7b26\u4e32",
    "\u73b0\u6709\u4e00\u4e2a n x n \u5927\u5c0f\u7684\u7f51\u683c\uff0c\u5de6\u4e0a\u89d2\u5355\u5143\u683c\u5750\u6807 (0, 0) \uff0c\u53f3\u4e0b\u89d2\u5355\u5143\u683c\u5750\u6807 (n - 1, n - 1) \u3002\u7ed9\u4f60\u6574\u6570 n \u548c\u4e00\u4e2a\u6574\u6570\u6570\u7ec4 startPos \uff0c\u5176\u4e2d startPos = [startrow, startcol] \u8868\u793a\u673a\u5668\u4eba\u6700\u5f00\u59cb\u5728\u5750\u6807\u4e3a (startrow, startcol) \u7684\u5355\u5143\u683c\u4e0a\u3002\n\n\u53e6\u7ed9\u4f60\u4e00\u4e2a\u957f\u5ea6\u4e3a m \u3001\u4e0b\u6807\u4ece 0 \u5f00\u59cb\u7684\u5b57\u7b26\u4e32 s \uff0c\u5176\u4e2d s[i] \u662f\u5bf9\u673a\u5668\u4eba\u7684\u7b2c i \u6761\u6307\u4ee4\uff1a'L'\uff08\u5411\u5de6\u79fb\u52a8\uff09\uff0c'R'\uff08\u5411\u53f3\u79fb\u52a8\uff09\uff0c'U'\uff08\u5411\u4e0a\u79fb\u52a8\uff09\u548c 'D'\uff08\u5411\u4e0b\u79fb\u52a8\uff09\u3002\n\n\u673a\u5668\u4eba\u53ef\u4ee5\u4ece s \u4e2d\u7684\u4efb\u4e00\u7b2c i \u6761\u6307\u4ee4\u5f00\u59cb\u6267\u884c\u3002\u5b83\u5c06\u4f1a\u9010\u6761\u6267\u884c\u6307\u4ee4\u76f4\u5230 s \u7684\u672b\u5c3e\uff0c\u4f46\u5728\u6ee1\u8db3\u4e0b\u8ff0\u6761\u4ef6\u4e4b\u4e00\u65f6\uff0c\u673a\u5668\u4eba\u5c06\u4f1a\u505c\u6b62\uff1a\n\n\t\u4e0b\u4e00\u6761\u6307\u4ee4\u5c06\u4f1a\u5bfc\u81f4\u673a\u5668\u4eba\u79fb\u52a8\u5230\u7f51\u683c\u5916\u3002\n\n\t\u6ca1\u6709\u6307\u4ee4\u53ef\u4ee5\u6267\u884c\u3002\n\n\u8fd4\u56de\u4e00\u4e2a\u957f\u5ea6\u4e3a m \u7684\u6570\u7ec4 answer \uff0c\u5176\u4e2d answer[i] \u662f\u673a\u5668\u4eba\u4ece\u7b2c i\u00a0\u6761\u6307\u4ee4 \u5f00\u59cb\u00a0\uff0c\u53ef\u4ee5\u6267\u884c\u7684 \u6307\u4ee4\u6570\u76ee \u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1an = 3, startPos = [0,1], s = \"RRDDLU\"\n\u8f93\u51fa\uff1a[1,5,4,3,1,0]\n\u89e3\u91ca\uff1a\u673a\u5668\u4eba\u4ece startPos \u51fa\u53d1\uff0c\u5e76\u4ece\u7b2c i \u6761\u6307\u4ee4\u5f00\u59cb\u6267\u884c\uff1a\n- 0: \"RRDDLU\" \u5728\u79fb\u52a8\u5230\u7f51\u683c\u5916\u4e4b\u524d\uff0c\u53ea\u80fd\u6267\u884c\u4e00\u6761 \"R\" \u6307\u4ee4\u3002\n- 1:  \"RDDLU\" \u53ef\u4ee5\u6267\u884c\u5168\u90e8\u4e94\u6761\u6307\u4ee4\uff0c\u673a\u5668\u4eba\u4ecd\u5728\u7f51\u683c\u5185\uff0c\u6700\u7ec8\u5230\u8fbe (0, 0) \u3002\n- 2:   \"DDLU\" \u53ef\u4ee5\u6267\u884c\u5168\u90e8\u56db\u6761\u6307\u4ee4\uff0c\u673a\u5668\u4eba\u4ecd\u5728\u7f51\u683c\u5185\uff0c\u6700\u7ec8\u5230\u8fbe (0, 0) \u3002\n- 3:    \"DLU\" \u53ef\u4ee5\u6267\u884c\u5168\u90e8\u4e09\u6761\u6307\u4ee4\uff0c\u673a\u5668\u4eba\u4ecd\u5728\u7f51\u683c\u5185\uff0c\u6700\u7ec8\u5230\u8fbe (0, 0) \u3002\n- 4:     \"LU\" \u5728\u79fb\u52a8\u5230\u7f51\u683c\u5916\u4e4b\u524d\uff0c\u53ea\u80fd\u6267\u884c\u4e00\u6761 \"L\" \u6307\u4ee4\u3002\n- 5:      \"U\" \u5982\u679c\u5411\u4e0a\u79fb\u52a8\uff0c\u5c06\u4f1a\u79fb\u52a8\u5230\u7f51\u683c\u5916\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1an = 2, startPos = [1,1], s = \"LURD\"\n\u8f93\u51fa\uff1a[4,1,0,0]\n\u89e3\u91ca\uff1a\n- 0: \"LURD\"\n- 1:  \"URD\"\n- 2:   \"RD\"\n- 3:    \"D\"\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1an = 1, startPos = [0,0], s = \"LRUD\"\n\u8f93\u51fa\uff1a[0,0,0,0]\n\u89e3\u91ca\uff1a\u65e0\u8bba\u673a\u5668\u4eba\u4ece\u54ea\u6761\u6307\u4ee4\u5f00\u59cb\u6267\u884c\uff0c\u90fd\u4f1a\u79fb\u52a8\u5230\u7f51\u683c\u5916\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\tm == s.length\n\n\t1 <= n, m <= 500\n\n\tstartPos.length == 2\n\n\t0 <= startrow, startcol < n\n\n\ts \u7531 'L'\u3001'R'\u3001'U' \u548c 'D' \u7ec4\u6210",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1an\u3001startPos\u3001s\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def executeInstructions(self, n: int, startPos: List[int], s: str) -> List[int]:\n        m = len(s)\n        ans = list()\n        for i in range(m):\n            x, y = startPos\n            cnt = m - i\n            for j in range(i, m):\n                ch = s[j]\n                if ch == \"L\":\n                    y -= 1\n                elif ch == \"R\":\n                    y += 1\n                elif ch == \"U\":\n                    x -= 1\n                else:\n                    x += 1\n                if x < 0 or x >= n or y < 0 or y >= n:\n                    cnt = j - i\n                    break\n            ans.append(cnt)\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.executeInstructions(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
