    "LeetCode 3324",
    "medium",
    "\u5b57\u7b26\u4e32",
    "\u7ed9\u4f60\u4e00\u4e2a\u5b57\u7b26\u4e32 target\u3002\n\nAlice \u5c06\u4f1a\u4f7f\u7528\u4e00\u79cd\u7279\u6b8a\u7684\u952e\u76d8\u5728\u5979\u7684\u7535\u8111\u4e0a\u8f93\u5165 target\uff0c\u8fd9\u4e2a\u952e\u76d8 \u53ea\u6709\u4e24\u4e2a \u6309\u952e\uff1a\n\n\t\u6309\u952e 1\uff1a\u5728\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u540e\u8ffd\u52a0\u5b57\u7b26 'a'\u3002\n\n\t\u6309\u952e 2\uff1a\u5c06\u5c4f\u5e55\u4e0a\u5b57\u7b26\u4e32\u7684 \u6700\u540e\u4e00\u4e2a \u5b57\u7b26\u66f4\u6539\u4e3a\u82f1\u6587\u5b57\u6bcd\u8868\u4e2d\u7684 \u4e0b\u4e00\u4e2a \u5b57\u7b26\u3002\u4f8b\u5982\uff0c'c' \u53d8\u4e3a 'd'\uff0c'z' \u53d8\u4e3a 'a'\u3002\n\n\u6ce8\u610f\uff0c\u6700\u521d\u5c4f\u5e55\u4e0a\u662f\u4e00\u4e2a\u7a7a\u5b57\u7b26\u4e32 \"\"\uff0c\u6240\u4ee5\u5979 \u53ea\u80fd \u6309\u6309\u952e 1\u3002\n\n\u8bf7\u4f60\u8003\u8651\u6309\u952e\u6b21\u6570 \u6700\u5c11 \u7684\u60c5\u51b5\uff0c\u6309\u5b57\u7b26\u4e32\u51fa\u73b0\u987a\u5e8f\uff0c\u8fd4\u56de Alice \u8f93\u5165 target \u65f6\u5c4f\u5e55\u4e0a\u51fa\u73b0\u7684\u6240\u6709\u5b57\u7b26\u4e32\u5217\u8868\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n\u8f93\u5165\uff1a target = \"abc\"\n\n\u8f93\u51fa\uff1a [\"a\",\"aa\",\"ab\",\"aba\",\"abb\",\"abc\"]\n\n\u89e3\u91ca\uff1a\n\nAlice \u6309\u952e\u7684\u987a\u5e8f\u5982\u4e0b\uff1a\n\n\t\u6309\u4e0b\u6309\u952e 1\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"a\"\u3002\n\n\t\u6309\u4e0b\u6309\u952e 1\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"aa\"\u3002\n\n\t\u6309\u4e0b\u6309\u952e 2\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"ab\"\u3002\n\n\t\u6309\u4e0b\u6309\u952e 1\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"aba\"\u3002\n\n\t\u6309\u4e0b\u6309\u952e 2\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"abb\"\u3002\n\n\t\u6309\u4e0b\u6309\u952e 2\uff0c\u5c4f\u5e55\u4e0a\u7684\u5b57\u7b26\u4e32\u53d8\u4e3a \"abc\"\u3002\n\n\u793a\u4f8b 2\uff1a\n\n\u8f93\u5165\uff1a target = \"he\"\n\n\u8f93\u51fa\uff1a [\"a\",\"b\",\"c\",\"d\",\"e\",\"f\",\"g\",\"h\",\"ha\",\"hb\",\"hc\",\"hd\",\"he\"]\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= target.length <= 400\n\n\ttarget \u4ec5\u7531\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u7ec4\u6210\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1atarget\u3002",
    "\u8f93\u51fa list<string> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def stringSequence(self, target: str) -> List[str]:\n        ans = [\"a\"]\n        while ans[-1] != target:\n            if target.startswith(ans[-1]): ans.append(ans[- 1] + \"a\")\n            else:  ans.append(ans[-1][: -1] + chr((ord(ans[-1][-1]) - 96) % 26 + 97))\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.stringSequence(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
