    "medium",
    "\u5b57\u7b26\u4e32",
    "\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u7684\u5b57\u7b26\u4e32\u00a0s\u00a0\uff0c\u5c06\u00a0s\u00a0\u4e2d\u7684\u5143\u7d20\u91cd\u65b0 \u6392\u5217\u00a0\u5f97\u5230\u65b0\u7684\u5b57\u7b26\u4e32\u00a0t\u00a0\uff0c\u5b83\u6ee1\u8db3\uff1a\n\n\t\u6240\u6709\u8f85\u97f3\u5b57\u6bcd\u90fd\u5728\u539f\u6765\u7684\u4f4d\u7f6e\u4e0a\u3002\u66f4\u6b63\u5f0f\u7684\uff0c\u5982\u679c\u6ee1\u8db3\u00a00 <= i < s.length\u00a0\u7684\u4e0b\u6807 i\u00a0\u5904\u7684\u00a0s[i]\u00a0\u662f\u4e2a\u8f85\u97f3\u5b57\u6bcd\uff0c\u90a3\u4e48\u00a0t[i] = s[i]\u00a0\u3002\n\n\t\u5143\u97f3\u5b57\u6bcd\u90fd\u5fc5\u987b\u4ee5\u4ed6\u4eec\u7684 ASCII\u00a0\u503c\u6309 \u975e\u9012\u51cf\u00a0\u987a\u5e8f\u6392\u5217\u3002\u66f4\u6b63\u5f0f\u7684\uff0c\u5bf9\u4e8e\u6ee1\u8db3\u00a00 <= i < j < s.length\u00a0\u7684\u4e0b\u6807 i\u00a0\u548c j\u00a0 \uff0c\u5982\u679c\u00a0s[i] \u548c\u00a0s[j]\u00a0\u90fd\u662f\u5143\u97f3\u5b57\u6bcd\uff0c\u90a3\u4e48\u00a0t[i]\u00a0\u7684 ASCII \u503c\u4e0d\u80fd\u5927\u4e8e\u00a0t[j]\u00a0\u7684 ASCII \u503c\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u7ed3\u679c\u5b57\u6bcd\u4e32\u3002\n\n\u5143\u97f3\u5b57\u6bcd\u4e3a\u00a0'a'\u00a0\uff0c'e'\u00a0\uff0c'i'\u00a0\uff0c'o'\u00a0\u548c\u00a0'u'\u00a0\uff0c\u5b83\u4eec\u53ef\u80fd\u662f\u5c0f\u5199\u5b57\u6bcd\u4e5f\u53ef\u80fd\u662f\u5927\u5199\u5b57\u6bcd\uff0c\u8f85\u97f3\u5b57\u6bcd\u662f\u9664\u4e86\u8fd9 5 \u4e2a\u5b57\u6bcd\u4ee5\u5916\u7684\u6240\u6709\u5b57\u6bcd\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"lEetcOde\"\n\u8f93\u51fa\uff1a\"lEOtcede\"\n\u89e3\u91ca\uff1a'E' \uff0c'O' \u548c 'e' \u662f s \u4e2d\u7684\u5143\u97f3\u5b57\u6bcd\uff0c'l' \uff0c't' \uff0c'c' \u548c 'd' \u662f\u6240\u6709\u7684\u8f85\u97f3\u3002\u5c06\u5143\u97f3\u5b57\u6bcd\u6309\u7167 ASCII \u503c\u6392\u5e8f\uff0c\u8f85\u97f3\u5b57\u6bcd\u7559\u5728\u539f\u5730\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"lYmpH\"\n\u8f93\u51fa\uff1a\"lYmpH\"\n\u89e3\u91ca\uff1as \u4e2d\u6ca1\u6709\u5143\u97f3\u5b57\u6bcd\uff08s \u4e2d\u90fd\u4e3a\u8f85\u97f3\u5b57\u6bcd\uff09\uff0c\u6240\u4ee5\u6211\u4eec\u8fd4\u56de \"lYmpH\" \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= s.length <= 105\n\n\ts\u00a0\u53ea\u5305\u542b\u82f1\u8bed\u5b57\u6bcd\u8868\u4e2d\u7684 \u5927\u5199\u00a0\u548c \u5c0f\u5199\u00a0\u5b57\u6bcd\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def sortVowels(self, s: str) -> str:\n        vowels = {\"a\", \"e\", \"i\", \"o\", \"u\", \"A\", \"E\", \"I\", \"O\", \"U\"}\n\n        tmp = [ch for ch in s if ch in vowels]\n\n        tmp.sort()\n\n        s_list = list(s)\n        idx = 0\n        for i in range(len(s_list)):\n            if s_list[i] in vowels:\n                s_list[i] = tmp[idx]\n                idx += 1\n\n        return \"\".join(s_list)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.sortVowels(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
