    "medium",
    "\u5b57\u7b26\u4e32",
    "Trie\uff08\u53d1\u97f3\u7c7b\u4f3c \"try\"\uff09\u6216\u8005\u8bf4 \u524d\u7f00\u6811 \u662f\u4e00\u79cd\u6811\u5f62\u6570\u636e\u7ed3\u6784\uff0c\u7528\u4e8e\u9ad8\u6548\u5730\u5b58\u50a8\u548c\u68c0\u7d22\u5b57\u7b26\u4e32\u6570\u636e\u96c6\u4e2d\u7684\u952e\u3002\u8fd9\u4e00\u6570\u636e\u7ed3\u6784\u6709\u76f8\u5f53\u591a\u7684\u5e94\u7528\u60c5\u666f\uff0c\u4f8b\u5982\u81ea\u52a8\u8865\u5b8c\u548c\u62fc\u5199\u68c0\u67e5\u3002\n\n\u8bf7\u4f60\u5b9e\u73b0 Trie \u7c7b\uff1a\n\n\tTrie() \u521d\u59cb\u5316\u524d\u7f00\u6811\u5bf9\u8c61\u3002\n\n\tvoid insert(String word) \u5411\u524d\u7f00\u6811\u4e2d\u63d2\u5165\u5b57\u7b26\u4e32 word \u3002\n\n\tboolean search(String word) \u5982\u679c\u5b57\u7b26\u4e32 word \u5728\u524d\u7f00\u6811\u4e2d\uff0c\u8fd4\u56de true\uff08\u5373\uff0c\u5728\u68c0\u7d22\u4e4b\u524d\u5df2\u7ecf\u63d2\u5165\uff09\uff1b\u5426\u5219\uff0c\u8fd4\u56de false \u3002\n\n\tboolean startsWith(String prefix) \u5982\u679c\u4e4b\u524d\u5df2\u7ecf\u63d2\u5165\u7684\u5b57\u7b26\u4e32\u00a0word \u7684\u524d\u7f00\u4e4b\u4e00\u4e3a prefix \uff0c\u8fd4\u56de true \uff1b\u5426\u5219\uff0c\u8fd4\u56de false \u3002\n\n\u00a0\n\n\u793a\u4f8b\uff1a\n\n```\n\u8f93\u5165\ninputs = [\"Trie\", \"insert\", \"search\", \"search\", \"startsWith\", \"insert\", \"search\"]\ninputs = [[], [\"apple\"], [\"apple\"], [\"app\"], [\"app\"], [\"app\"], [\"app\"]]\n\u8f93\u51fa\n[null, null, true, false, true, null, true]\n\n\u89e3\u91ca\nTrie trie = new Trie();\ntrie.insert(\"apple\");\ntrie.search(\"apple\");   // \u8fd4\u56de True\ntrie.search(\"app\");     // \u8fd4\u56de False\ntrie.startsWith(\"app\"); // \u8fd4\u56de True\ntrie.insert(\"app\");\ntrie.search(\"app\");     // \u8fd4\u56de True\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= word.length, prefix.length <= 2000\n\n\tword \u548c prefix \u4ec5\u7531\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u7ec4\u6210\n\n\tinsert\u3001search \u548c startsWith \u8c03\u7528\u6b21\u6570 \u603b\u8ba1 \u4e0d\u8d85\u8fc7 3 * 104 \u6b21\n\n\u00a0\n\n\u00a0\n\n\u6ce8\u610f\uff1a\u672c\u9898\u4e0e\u4e3b\u7ad9 208 \u9898\u76f8\u540c\uff1ahttps://leetcode.cn/problems/implement-trie-prefix-tree/",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1ainputs\u3001inputs\u3002",
    "\u8f93\u51fa list<String> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass Trie:\n    def __init__(self):\n        self.children = [None] * 26\n        self.isEnd = False\n    \n    def searchPrefix(self, prefix: str) -> \"Trie\":\n        node = self\n        for ch in prefix:\n            ch = ord(ch) - ord(\"a\")\n            if not node.children[ch]:\n                return None\n            node = node.children[ch]\n        return node\n\n    def insert(self, word: str) -> None:\n        node = self\n        for ch in word:\n            ch = ord(ch) - ord(\"a\")\n            if not node.children[ch]:\n                node.children[ch] = Trie()\n            node = node.children[ch]\n        node.isEnd = True\n\n    def search(self, word: str) -> bool:\n        node = self.searchPrefix(word)\n        return node is not None and node.isEnd\n\n    def startsWith(self, prefix: str) -> bool:\n        return self.searchPrefix(prefix) is not None\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = Trie(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
